const input=$input.first().json;
const confirmationText=typeof input.confirmationText==='string'?input.confirmationText.trim():'';
const suppliedToken=typeof input.confirmationToken==='string'?input.confirmationToken.trim():'';
const match=confirmationText.match(/^\s*confirmar\s+(offer_[A-Za-z0-9_-]{16,128})\s*[.!?]*\s*$/i);
const token=match?match[1]:suppliedToken;
const valid=Boolean(match)&&token===match[1]&&/^offer_[A-Za-z0-9_-]{16,128}$/.test(token);
return [{json:{...input,confirmationText,confirmationToken:token,booking_route:valid?'lookup_offer':'human_review',validation_message:valid?'Confirmación explícita válida; se verificará la oferta operativa.':'La reserva requiere el texto CONFIRMAR seguido del código de la propuesta vigente.'}}];

const request=$('Lógica — Validar confirmación explícita').first().json;
const offer=$input.first().json;
const text=value=>typeof value==='string'?value.trim():'';
const expiration=new Date(text(offer.expiresAt));
const ownerMatches=text(offer.contactPhone)===''||text(request.from)===''||text(offer.contactPhone)===text(request.from);
const changeType=text(offer.changeType)||'new';
const rawTarget=text(offer.targetReservationEventId);
let targetReservationEventIds=[];
if(changeType==='cancel_batch'){try{const parsed=JSON.parse(rawTarget);targetReservationEventIds=Array.isArray(parsed)?[...new Set(parsed.map(text).filter(Boolean))]:[]}catch{targetReservationEventIds=[];}}
else if(rawTarget)targetReservationEventIds=[rawTarget];
const targetValid=['reschedule','cancel'].includes(changeType)?targetReservationEventIds.length===1:changeType==='cancel_batch'?targetReservationEventIds.length>1:true;
const valid=text(offer.offerToken)===text(request.confirmationToken)&&text(offer.status)==='offered'&&text(offer.calendarId)!==''&&text(offer.slotStart)!==''&&text(offer.slotEnd)!==''&&text(offer.timezone)==='America/Argentina/Buenos_Aires'&&ownerMatches&&['new','reschedule','cancel','cancel_batch'].includes(changeType)&&targetValid&&!Number.isNaN(expiration.getTime())&&expiration.getTime()>Date.now();
return [{json:{...request,requestedStart:valid?text(offer.slotStart):'',requestedEnd:valid?text(offer.slotEnd):'',calendarId:valid?text(offer.calendarId):'',timezone:valid?'America/Argentina/Buenos_Aires':'',meetingTitle:valid?'Reunión — Consultora demo':'',meetingDescription:valid?'Reserva confirmada explícitamente por el contacto.':'',changeType:valid?changeType:'',targetReservationEventId:valid?rawTarget:'',targetReservationEventIds:valid?targetReservationEventIds:[],cancellationCount:valid?targetReservationEventIds.length:0,offer_route:valid?'consume':'human_review',offer_validation_message:valid?'Oferta vigente y coincidente.':'La oferta no existe, venció, pertenece a otro contacto o ya fue utilizada.'}}];

const request=$('Lógica — Validar oferta vigente').first().json;
const updated=$input.first().json;
const valid=updated.offerToken===request.confirmationToken&&updated.status==='consumed_pending';
return [{json:{...request,consumption_route:valid?'create':'human_review',consumption_message:valid?'Oferta consumida de forma única.':'No se pudo consumir la oferta de forma única.'}}];

const row=$input.first().json;
const expected=$('Lógica — Validar confirmación explícita').first().json;
const valid=row.offerToken===expected.confirmationToken&&row.status==='reserved'&&typeof row.reservationEventId==='string'&&row.reservationEventId.length>0;
return [{json:{...expected,registration_route:valid?'success':'human_review',registration_message:valid?'Reserva registrada.':'La reunión se creó, pero su registro operativo requiere revisión humana.'}}];

const source=$('Lógica — Validar oferta vigente').first().json;
const fullName=typeof source.contactName==='string'?source.contactName.trim():'';
const phone=typeof source.from==='string'?source.from.trim():'';
const change=source.changeType||'new';
const message=change==='cancel_batch'?`${source.cancellationCount||0} reuniones canceladas por confirmación explícita.`:change==='cancel'?'Reunión cancelada por confirmación explícita.':change==='reschedule'?`Reunión reprogramada para ${source.requestedStart}.`:`Reserva confirmada para ${source.requestedStart}.`;
return [{json:{fullName,phone,message,receivedAt:source.receivedAt,source:'whatsapp',interactionKey:`${change}:${source.confirmationToken}`}}];

const source=$('Lógica — Validar oferta vigente').first().json;
const ids=Array.isArray(source.targetReservationEventIds)?source.targetReservationEventIds:[source.targetReservationEventId];
const unique=[...new Set(ids.map(value=>String(value||'').trim()).filter(Boolean))];
if(!unique.length)throw new Error('No hay reuniones válidas para cancelar.');
return unique.map(targetReservationEventId=>({json:{...source,targetReservationEventId,cancellationCount:unique.length}}));

const source=$('Lógica — Validar oferta vigente').first().json;
const expected=Array.isArray(source.targetReservationEventIds)?source.targetReservationEventIds.length:1;
const completed=$input.all();
if(completed.length!==expected)throw new Error(`Se cancelaron ${completed.length} de ${expected} reuniones; requiere revisión.`);
return [{json:{...source,cancellationCount:expected}}];
